-- Project templates (Projects workspace, Phase 4 step 1) — run once in the Supabase SQL Editor,
-- after projects.sql. Safe to run again: it never overwrites templates you have edited.

-- 1. Project type on each project (the name of the template it was created from)
alter table projects add column if not exists project_type text;

-- 2. Templates: one row per project type, with the starter checklist per stage
--    tasks = { "Site Visit": ["task", ...], "Design": [...], ... }
create table if not exists project_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  description text,
  tasks jsonb not null default '{}'::jsonb,
  sort integer not null default 0,
  active boolean not null default true,   -- false = hidden from the New project form
  created_by text,
  updated_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
drop trigger if exists project_templates_touch on project_templates;
create trigger project_templates_touch before update on project_templates for each row execute function projects_touch_updated_at();

alter table project_templates enable row level security;
drop policy if exists "Signed-in users manage project_templates" on project_templates;
create policy "Signed-in users manage project_templates" on project_templates for all to authenticated using (true) with check (true);

-- 3. Starter templates (only added if a template with that name doesn't exist yet)
